import { createHash } from 'node:crypto';
import { copyFile, mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
const source = new URL('node_modules/@mediapipe/tasks-vision/', root);
const target = new URL('public/mediapipe/', root);
const { version } = JSON.parse(await readFile(new URL('package.json', source), 'utf8'));
if (version !== '0.10.32') throw new Error('Review and verify camera assets before changing MediaPipe 0.10.32.');
await mkdir(new URL('wasm/', target), { recursive: true });
// The pinned package provides CJS and ESM. A classic-worker wrapper is needed
// because the WASM loader uses importScripts(), unavailable in module workers.
const bundle = await readFile(new URL('vision_bundle.cjs', source), 'utf8');
if (/\brequire\s*\(/.test(bundle)) throw new Error('The vision bundle has an unexpected runtime dependency.');
await writeFile(new URL('vision_bundle.js', target), `/* MediaPipe Tasks Vision ${version}, Apache-2.0. Generated by scripts/prepare-camera-assets.mjs. */\nvar Vision = (function () {\nconst exports = {};\n${bundle.replace(/\/\/# sourceMappingURL=.*$/m, '')}\nreturn exports;\n})();\n`);
for (const name of await readdir(new URL('wasm/', source))) {
  if (name.endsWith('.js') || name.endsWith('.wasm')) {
    await copyFile(new URL(`wasm/${name}`, source), new URL(`wasm/${name}`, target));
  }
}
const models = {
  'pose_landmarker_lite.task': '59929e1d1ee95287735ddd833b19cf4ac46d29bc7afddbbf6753c459690d574a',
  'face_landmarker.task': '64184e229b263107bc2b804c6625db1341ff2bb731874b0bcc2fe6544e0bc9ff',
};
for (const [name, checksum] of Object.entries(models)) {
  const model = await readFile(new URL(name, target));
  const digest = createHash('sha256').update(model).digest('hex');
  if (digest !== checksum) throw new Error(`Unexpected ${name} checksum: ${digest}`);
}
console.log(`Prepared MediaPipe ${version} for local camera tracking (${fileURLToPath(target)}).`);
